program:
(()=>{

const $ = id => document.getElementById(id);
const WA = FMI.phone;           /* the family's WhatsApp in a real invitation */
const TARGET = FMI.target;
const calm = FMI.reduceMotion || matchMedia("(prefers-reduced-motion: reduce)").matches;
const params = new URLSearchParams(FMI.search);
const preview = false;

/* guest name from ?to=Kumar-Family */
let guest = "";
try {
  guest = (params.get("to") || "").replace(/[-_+]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 40);
  guest = guest.split(" ").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
} catch (e) {}
if (guest) {
  $("dear").textContent = "Dear " + guest + ",";
  $("g-dear").textContent = "Dear " + guest + ","; $("g-dear").hidden = false;
  $("r-name").value = guest; $("b-name").value = guest;
  document.title = "Dear " + guest + " · Senthil & Abirami's Wedding";
}

/* sounds, made in the browser */
let actx, noiseBuf;
function ac(){ try { actx = actx || new (window.AudioContext || window.webkitAudioContext)(); if (actx.state === "suspended") actx.resume(); } catch (e) {} return actx; }
const live = () => actx && actx.state === "running";
function noise(when, dur, type, freq, q, gain){
  const c = ac(); if (!c) return;
  try {
    if (!noiseBuf) { noiseBuf = c.createBuffer(1, c.sampleRate * 2, c.sampleRate); const d = noiseBuf.getChannelData(0); for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1; }
    const t0 = c.currentTime + (when || 0), s = c.createBufferSource(); s.buffer = noiseBuf;
    const f = c.createBiquadFilter(); f.type = type; f.frequency.value = freq; f.Q.value = q;
    const g = c.createGain(); g.gain.setValueAtTime(gain, t0); g.gain.exponentialRampToValueAtTime(.0001, t0 + dur);
    s.connect(f); f.connect(g); g.connect(c.destination); s.start(t0, Math.random()); s.stop(t0 + dur + .05);
  } catch (e) {}
}
function thump(when, f0, f1, dur, gain){
  const c = ac(); if (!c) return;
  try {
    const t0 = c.currentTime + (when || 0), o = c.createOscillator(), g = c.createGain();
    o.type = "sine"; o.frequency.setValueAtTime(f0, t0); o.frequency.exponentialRampToValueAtTime(f1, t0 + dur * .6);
    g.gain.setValueAtTime(gain, t0); g.gain.exponentialRampToValueAtTime(.0001, t0 + dur);
    o.connect(g); g.connect(c.destination); o.start(t0); o.stop(t0 + dur + .05);
  } catch (e) {}
}
function chime(base, gain, when){
  const c = ac(); if (!c) return;
  try {
    const t0 = c.currentTime + .02 + (when || 0), out = c.createGain(); out.gain.value = gain || .05; out.connect(c.destination);
    [[1, 1, 2.4], [2.76, .45, 1.6], [5.4, .22, 1], [8.9, .08, .5]].forEach(([r, g, d]) => {
      const o = c.createOscillator(); o.type = "sine"; o.frequency.value = base * r;
      const v = c.createGain(); v.gain.setValueAtTime(0, t0); v.gain.linearRampToValueAtTime(g, t0 + .006); v.gain.exponentialRampToValueAtTime(.0001, t0 + d);
      o.connect(v); v.connect(out); o.start(t0); o.stop(t0 + d + .05);
    });
  } catch (e) {}
}
const rustle = () => { for (let i = 0; i < 7; i++) noise(i * .05 + Math.random() * .03, .09 + Math.random() * .08, "bandpass", 2600 + Math.random() * 3200, 1.2, .14); };
const thavil = (w, g) => { thump(w || 0, 150, 55, .5, g || .5); noise(w || 0, .07, "bandpass", 1700, 1.4, (g || .5) * .7); };
function melam(){ for (let i = 0; i < 22; i++) { const t = 1.5 * Math.pow(i / 22, .8); thavil(t, .18 + i / 22 * .4); } thavil(1.62, .8); [659.25, 830.6, 987.8, 1318.5].forEach((f, i) => chime(f, .045, 1.65 + i * .08)); }

/* music: starts with the bundle; the button hides itself if no song is loaded */
const music = $("music"), mBtn = $("music-btn");
let musicWanted = false, noMusic = false;
music.addEventListener("error", () => { noMusic = true; mBtn.hidden = true; });
function paintMusic(){ mBtn.classList.toggle("on", musicWanted); mBtn.setAttribute("aria-pressed", musicWanted); mBtn.setAttribute("aria-label", musicWanted ? "Pause music" : "Play music"); }
function setMusic(on){
  musicWanted = on;
  if (on && !noMusic) { music.volume = .75; const p = music.play(); if (p) p.catch(() => { musicWanted = false; paintMusic(); }); }
  else music.pause();
  paintMusic();
}
mBtn.addEventListener("click", () => setMusic(!musicWanted));
document.addEventListener("visibilitychange", () => { if (document.hidden) music.pause(); else if (musicWanted && !noMusic) music.play().catch(() => {}); });

/* akshathai: turmeric rice, petals and jasmine */
const cv = $("fx"), cx = cv.getContext("2d");
let bits = [], fxRun = false, fxLast = 0;
function sizeCv(){ const d = Math.min(2, devicePixelRatio || 1); cv.width = innerWidth * d; cv.height = innerHeight * d; cx.setTransform(d, 0, 0, d, 0, 0); }
sizeCv();
const KINDS = [["rice", "#F0C030"], ["rice", "#E8A317"], ["rice", "#F6D15A"], ["rice", "#E8A317"], ["rice", "#F0C030"], ["rice", "#DE9B12"], ["rice", "#F6D15A"], ["rice", "#E8A317"], ["petal", "#C8102E"], ["petal", "#E0405A"], ["jas", "#FFFDF4"]];
function bit(x, y, vx, vy){ const k = KINDS[Math.floor(Math.random() * KINDS.length)]; return { x, y, vx, vy, k: k[0], c: k[1], r: Math.random() * 6.3, vr: (Math.random() - .5) * 9, s: k[0] === "rice" ? 1 : k[0] === "jas" ? 1 + Math.random() * .3 : 1.1 + Math.random() * .4, ph: Math.random() * 6.3 }; }
function burst(x, y, n, power){
  if (calm) return;
  for (let i = 0; i < n; i++) { const a = -Math.PI / 2 + (Math.random() - .5) * 2.4, s = power * (.35 + Math.random() * .75); bits.push(bit(x, y, Math.cos(a) * s, Math.sin(a) * s)); }
  start();
}
function rain(n){
  if (calm) return;
  const r = document.querySelector(".inv").getBoundingClientRect();
  for (let i = 0; i < n; i++) bits.push(bit(r.left + Math.random() * r.width, -20 - Math.random() * innerHeight * .5, (Math.random() - .5) * 40, 80 + Math.random() * 120));
  start();
}
function start(){ if (bits.length > 700) bits.splice(0, bits.length - 700); if (!fxRun) { fxRun = true; fxLast = performance.now(); requestAnimationFrame(step); } }
function step(t){
  const dt = Math.min(.033, (t - fxLast) / 1000); fxLast = t;
  cx.clearRect(0, 0, innerWidth, innerHeight);
  bits = bits.filter(b => b.y < innerHeight + 30);
  for (const b of bits) {
    const lift = b.k === "rice" ? 1 : .45;
    b.vy = Math.min(b.vy + 980 * lift * dt, b.k === "rice" ? 420 : 140); b.vx *= .985;
    b.x += (b.vx + (b.k === "rice" ? 0 : Math.sin(t / 380 + b.ph) * 30)) * dt; b.y += b.vy * dt; b.r += b.vr * dt;
    cx.save(); cx.translate(b.x, b.y); cx.rotate(b.r); cx.fillStyle = b.c;
    if (b.k === "rice") { cx.beginPath(); cx.ellipse(0, 0, 1.4, 3.4, 0, 0, 6.3); cx.fill(); }
    else if (b.k === "petal") { cx.scale(1, Math.cos(b.r * 1.3) * .5 + .7); cx.beginPath(); cx.ellipse(0, 0, 3.4 * b.s, 5 * b.s, 0, 0, 6.3); cx.fill(); }
    else { for (let i = 0; i < 5; i++) { cx.rotate(1.2566); cx.beginPath(); cx.ellipse(0, -2.6 * b.s, 1.5 * b.s, 2.6 * b.s, 0, 0, 6.3); cx.fill(); } }
    cx.restore();
  }
  if (bits.length) requestAnimationFrame(step); else { fxRun = false; cx.clearRect(0, 0, innerWidth, innerHeight); }
}
addEventListener("resize", sizeCv);

/* leaves: each one flips into place and its letters are rubbed in with soot */
function showLadder(l){ l.classList.add("on"); }
const coverLadder = $("cover-ladder");
const leafIO = "IntersectionObserver" in window ? new IntersectionObserver(es => es.forEach(e => {
  if (!e.isIntersecting) return;
  const el = e.target; el.classList.add("on"); leafIO.unobserve(el);
  const l = el.closest(".ladder"); if (l) showLadder(l);
  if (live() && el.querySelector(".t-name")) setTimeout(rustle, 150);
}), { threshold: .35 }) : null;
document.querySelectorAll(".ladder").forEach(l => {
  if (l === coverLadder) return;
  [...l.querySelectorAll(".leaf")].forEach((lf, i) => { lf.style.setProperty("--dl", (i % 3) * .12 + "s"); leafIO ? leafIO.observe(lf) : lf.classList.add("on"); });
  if (!leafIO) l.classList.add("on");
});
function openCover(){ showLadder(coverLadder); coverLadder.querySelectorAll(".leaf").forEach(l => l.classList.add("on")); }

/* gate: untie the thread, the leaves fan open */
const gate = $("gate");
let opened = false;
function untie(){
  if (opened) return; opened = true;
  ac(); setMusic(true); if (!noMusic) mBtn.hidden = false;
  gate.classList.add("untie"); noise(0, .25, "bandpass", 1200, .8, .2);
  setTimeout(() => { gate.classList.add("fan"); rustle(); }, calm ? 0 : 650);
  setTimeout(() => { document.body.classList.remove("locked"); gate.classList.add("gone"); chime(659.25, .05); openCover(); }, calm ? 200 : 1900);
  setTimeout(() => { gate.hidden = true; }, calm ? 900 : 3000);
}
$("open").addEventListener("click", untie);
$("bundle").addEventListener("click", untie);
if (preview) { gate.hidden = true; document.body.classList.remove("locked"); openCover(); }
if (calm) openCover();
const setBW = () => { const b = $("bundle").getBoundingClientRect().width; $("bundle").style.setProperty("--bw", b + "px"); };
setBW(); addEventListener("resize", setBW);

/* reveal on view */
const io = "IntersectionObserver" in window ? new IntersectionObserver(es => es.forEach(e => {
  if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
}), { threshold: .12 }) : null;
document.querySelectorAll(".rv").forEach(el => io ? io.observe(el) : el.classList.add("in"));

/* the couple: tap anywhere on the photo to shower akshathai */
let showered = false;
$("couple").addEventListener("click", e => {
  ac(); const r = $("couple").getBoundingClientRect();
  const x = e.clientX || r.left + r.width / 2, y = e.clientY || r.top + r.height * .45;
  burst(x, y, 80, 620); noise(0, .35, "highpass", 3800, .7, .06); chime(1046.5, .03);
});
if ("IntersectionObserver" in window) new IntersectionObserver(([e], o) => {
  if (e.isIntersecting && !showered) { showered = true; rain(60); o.disconnect(); }
}, { threshold: .5 }).observe($("couple"));

/* scroll engine: the three knots */
const knot = $("s-knot"), caps = [...$("k-caps").children], marks = [...$("knots").children];
const root = document.documentElement;
let kState = 0, ticking = false;
function setKnot(n){
  if (n === kState) return;
  const forward = n > kState; kState = n;
  caps.forEach((c, i) => c.classList.toggle("on", i === n));
  marks.forEach((m, i) => m.classList.toggle("on", n > i));
  if (!forward || calm) return;
  if (n >= 1 && n <= 3) { if (live()) thavil(0, .55); rain(18 + n * 8); }
  if (n === 4) { if (live()) melam(); setTimeout(() => rain(110), 1500); }
}
function update(){
  const vh = innerHeight, r = knot.getBoundingClientRect();
  const p = calm ? 1 : Math.min(1, Math.max(0, -r.top / Math.max(1, r.height - vh)));
  knot.style.setProperty("--p", p.toFixed(4));
  setKnot(calm ? 4 : p < .2 ? 0 : p < .42 ? 1 : p < .62 ? 2 : p < .8 ? 3 : 4);
  const max = root.scrollHeight - vh;
  root.style.setProperty("--gp", max > 0 ? (scrollY / max).toFixed(4) : 0);
  ticking = false;
}
addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
addEventListener("resize", update);
update();

/* etch your blessing: letters scratched in one by one */
const etchTx = $("etch-tx"), stylus = $("stylus"), etchLeaf = $("etch-leaf");
let etching = false;
function placeStylus(){
  const spans = etchTx.querySelectorAll("span.c"); const last = spans[spans.length - 1]; if (!last) return;
  const lr = etchLeaf.getBoundingClientRect(), r = last.getBoundingClientRect();
  stylus.style.left = (r.right - lr.left - 2) + "px"; stylus.style.top = (r.bottom - lr.top - 9) + "px";
}
async function etch(text, from){
  etching = true;
  etchTx.classList.add("rub"); noise(0, .5, "bandpass", 900, .6, .08);
  await new Promise(r => setTimeout(r, calm ? 0 : 550));
  etchTx.innerHTML = ""; etchTx.classList.remove("rub");
  const chars = [...text];
  if (calm) { etchTx.textContent = text; } else {
    stylus.classList.add("on");
    for (let i = 0; i < chars.length; i++) {
      const s = document.createElement("span"); s.className = "c"; s.textContent = chars[i]; etchTx.appendChild(s);
      placeStylus(); if (live() && chars[i] !== " " && i % 2 === 0) noise(0, .03, "highpass", 4200, .8, .07);
      await new Promise(r => setTimeout(r, chars[i] === " " ? 30 : 48));
    }
    stylus.classList.remove("on");
  }
  const f = document.createElement("span"); f.className = "from"; f.textContent = from; etchTx.appendChild(f);
  chime(987.8, .045); etching = false;
}
$("bless").addEventListener("submit", async e => {
  e.preventDefault(); if (etching) return; ac();
  const name = $("b-name").value.trim() || "A well-wisher", text = $("b-text").value.trim() || "May you two be blessed with a long, happy life together.";
  if (!await FMI.interactions.save("wish",{name,message:text})) return;
  etch(text, name);
  $("bless-wa").href = "https://wa.me/" + WA + "?text=" + encodeURIComponent("A blessing for Senthil & Abirami 🌼\n\n" + text + "\n\n" + name);
  $("bless-wa").hidden = false;
});
if (guest) etchTx.querySelector(".from").textContent = guest;

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
  if (s <= 0) { $("count").innerHTML = '<p style="grid-column:1/-1;font-size:1.3rem;font-style:italic">Senthil and Abirami are married. Thank you for your blessings!</p>'; return; }
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  cells.d.textContent = d;
  cells.h.textContent = String(h).padStart(2, "0");
  cells.m.textContent = String(m).padStart(2, "0");
  cells.s.textContent = String(s).padStart(2, "0");
  setTimeout(tick, 1000 - Date.now() % 1000);
}
tick();

/* calendar: Apple devices open the .ics, others get Google Calendar */
const CAL = FMI.calendar({
  reception: { t: "Senthil & Abirami · Reception", d: "20270203T133000Z/20270203T163000Z", l: "Heritage Madurai, Madurai" },
  muhurtham: { t: "Senthil & Abirami · Muhurtham", d: "20270204T020000Z/20270204T033000Z", l: "Thiruparankundram, Madurai" }
});
if (!/iPhone|iPad|iPod|Macintosh/.test(navigator.userAgent)) document.querySelectorAll("[data-cal]").forEach(a => {
  const c = CAL[a.dataset.cal];
  a.href = "https://calendar.google.com/calendar/render?action=TEMPLATE&text=" + encodeURIComponent(c.t) + "&dates=" + c.d + "&location=" + encodeURIComponent(c.l) + "&details=" + encodeURIComponent("Invitation: https://findmyinvite.com/");
  a.target = "_blank"; a.rel = "noopener";
});

/* rsvp */
let guests = 2;
$("g-minus").addEventListener("click", () => { guests = Math.max(1, guests - 1); $("g-count").textContent = guests; });
$("g-plus").addEventListener("click", () => { guests = Math.min(20, guests + 1); $("g-count").textContent = guests; });
const form = $("rsvp-form");
form.addEventListener("change", () => {
  $("att-yes").style.display = form.querySelector("input[name=att]:checked").value === "yes" ? "grid" : "none";
});
form.addEventListener("submit", e => {
  e.preventDefault();
  const name = $("r-name").value.trim();
  if (!name) { $("r-err").hidden = false; $("r-name").focus(); return; }
  $("r-err").hidden = true;
  const yes = form.querySelector("input[name=att]:checked").value === "yes";
  const lines = ["RSVP · Senthil & Abirami's Wedding 🌼", "", "Name: " + name, "Attending: " + (yes ? "Yes, with our blessings" : "Sorry, can't make it")];
  if (yes) {
    lines.push("For: " + ([...form.querySelectorAll("input[name=fn]:checked")].map(i => i.value).join(", ") || "Not sure yet"));
    lines.push("Guests: " + guests);
  }
  const w = $("r-msg").value.trim(); if (w) lines.push("Note: " + w);
  const url = "https://wa.me/" + WA + "?text=" + encodeURIComponent(lines.join("\n"));
  const win = FMI.open(url, "_blank"); if (!win) FMI.open(url);
});

/* share */
function toast(t){ const el = $("toast"); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2200); }
$("share").addEventListener("click", async () => {
  const url = location.origin + FMI.instanceKey;
  try {
    if (navigator.share) { await FMI.share({ title: "Senthil & Abirami · Wedding Invitation", text: "You're invited to Senthil & Abirami's wedding on 4 February 2027 in Madurai", url }); return; }
    await FMI.copyLink(url); toast("Invitation link copied");
  } catch (e) { if (e && e.name !== "AbortError") toast(url); }
});

const guestWall=document.createElement('div');guestWall.id='fmi-wish-wall';$('bless').after(guestWall);FMI.interactions.subscribe(data=>{guestWall.replaceChildren();for(const wish of data.wishes){const item=document.createElement('blockquote'),message=document.createElement('p'),name=document.createElement('cite');item.dataset.fmiGuest='true';message.textContent=wish.message;name.textContent=wish.name;item.append(message,name);guestWall.append(item);}});
FMI.ready();
})();
